() => {
  const f = document.getElementById('flyer');
  const r = f.getBoundingClientRect();
  const rows = [...f.children].map(c => {
    const b = c.getBoundingClientRect();
    return {cls: c.className||c.tagName, x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height)};
  });
  const overflow = {sw: f.scrollWidth, sh: f.scrollHeight};
  const fontOK = document.fonts.check('800 78px Inter');
  const img = f.querySelector('.photo img');
  const cands = [...f.querySelectorAll('.cand')].map(c=>{const b=c.getBoundingClientRect();return [Math.round(b.x),Math.round(b.width)]});
  const nmOverflow = [...f.querySelectorAll('.nm,.ro,.cta span,.step span,footer')].map(e=>({t:e.textContent.slice(0,18), sw:e.scrollWidth, cw:e.clientWidth, ow:e.offsetWidth}));
  return {r:{w:r.width,h:r.height}, rows, overflow, fontOK, imgNat:[img.naturalWidth,img.naturalHeight], cands, nmOverflow};
}

