() => {
  const f = document.getElementById('flyer');
  const bad = [];
  f.querySelectorAll('*').forEach(e=>{
    if (e.scrollWidth > e.clientWidth + 1 && getComputedStyle(e).overflow !== 'hidden') bad.push([e.className||e.tagName, e.scrollWidth, e.clientWidth]);
  });
  const fr = f.getBoundingClientRect();
  const out = [];
  f.querySelectorAll('h1,.cand,.cta,.step,footer').forEach(e=>{
    const b = e.getBoundingClientRect();
    if (b.top < fr.top-0.5 || b.bottom > fr.bottom+0.5 || b.left < fr.left-0.5 || b.right > fr.right+0.5)
      out.push([e.className||e.tagName, b.top, b.bottom, b.left, b.right]);
  });
  return {bad, out, sh:f.scrollHeight, sw:f.scrollWidth};
}

